package android.database.sqlite;
import java.io.*;import java.sql.*;import java.util.*;import android.content.ContentValues;import android.database.Cursor;
public class SQLiteDatabase{public static final int CONFLICT_REPLACE=5;private Connection db;private boolean ok;public static SQLiteDatabase openOrCreateDatabase(File file,Object ignored){try{Class.forName("org.sqlite.JDBC");SQLiteDatabase d=new SQLiteDatabase();d.db=DriverManager.getConnection("jdbc:sqlite:"+file);return d;}catch(Exception e){throw new RuntimeException(e);}}public boolean enableWriteAheadLogging(){execSQL("PRAGMA journal_mode=WAL");return true;}public void execSQL(String sql){try(Statement s=db.createStatement()){s.execute(sql);}catch(Exception e){throw new RuntimeException(e);}}
 public Cursor rawQuery(String sql,String[] args){try{PreparedStatement s=db.prepareStatement(sql);if(args!=null)for(int i=0;i<args.length;i++)s.setString(i+1,args[i]);ResultSet r=s.executeQuery();return new Cursor(){public boolean moveToFirst(){return moveToNext();}public boolean moveToNext(){try{return r.next();}catch(Exception e){throw new RuntimeException(e);}}public String getString(int i){try{return r.getString(i+1);}catch(Exception e){throw new RuntimeException(e);}}public void close(){try{r.close();s.close();}catch(Exception e){throw new RuntimeException(e);}}};}catch(Exception e){throw new RuntimeException(e);}}
 public long insertOrThrow(String table,String ignored,ContentValues row){return insertWithOnConflict(table,ignored,row,0);}public long insertWithOnConflict(String table,String ignored,ContentValues row,int conflict){String cols=String.join(",",row.keySet()),slots=String.join(",",Collections.nCopies(row.size(),"?"));try(PreparedStatement s=db.prepareStatement("INSERT "+(conflict==5?"OR REPLACE ":"")+"INTO "+table+" ("+cols+") VALUES ("+slots+")")){int i=1;for(Object v:row.values())s.setObject(i++,v);s.executeUpdate();return 1;}catch(Exception e){throw new RuntimeException(e);}}
 public int delete(String table,String where,String[] args){return updateSql("DELETE FROM "+table+" WHERE "+where,Arrays.asList(args));}private int updateSql(String sql,List<?> values){try(PreparedStatement s=db.prepareStatement(sql)){int i=1;for(Object v:values)s.setObject(i++,v);return s.executeUpdate();}catch(Exception e){throw new RuntimeException(e);}}public int update(String table,ContentValues row,String where,String[] args){List<Object> values=new ArrayList<>(row.values());values.addAll(Arrays.asList(args));List<String> fields=new ArrayList<>();for(String k:row.keySet())fields.add(k+"=?");return updateSql("UPDATE "+table+" SET "+String.join(",",fields)+" WHERE "+where,values);}
 public void beginTransaction(){try{ok=false;db.setAutoCommit(false);}catch(Exception e){throw new RuntimeException(e);}}public void setTransactionSuccessful(){ok=true;}public void endTransaction(){try{if(ok)db.commit();else db.rollback();db.setAutoCommit(true);}catch(Exception e){throw new RuntimeException(e);}}
}
